arguments.command:
cd /workspace && (python3 -c "import docx" 2>/dev/null || pip install python-docx -q) && python3 - <<'EOF'
import docx
d = docx.Document('对话附件/IIRE2027_参展邀请函.docx')
print("=== PARAGRAPHS ===")
for p in d.paragraphs:
    t = p.text.strip()
    if t: print(t)
print("=== TABLES ===")
for i, tb in enumerate(d.tables):
    print(f"--- table {i} ---")
    for row in tb.rows:
        print(' | '.join(c.text.strip() for c in row.cells))
EOF
